#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <number>\n", argv[0]);
        return 1;
    }

    char *endptr;
    long num = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        printf("Invalid input: %s\n", argv[1]);
        return 1;
    }

    if (num < -1000 || num > 1000) {
        printf("Number out of range: %ld\n", num);
        return 1;
    }

    long result = 0;
    for (int i = 0; i < 10; i++) {
        result = result * 10 + num % 10;
        num /= 10;
    }

    printf("%ld\n", result);

    return 0;
}
